import sys

data = sys.stdin.read().split()
s = data[0]
last = {}
for i in range(len(s)):
    last[s[i]] = i
o = []
st = 0
end = 0
for i in range(len(s)):
    if last[s[i]] > end:
        end = last[s[i]]
    if i == end:
        o.append(end - st + 1)
        st = i + 1
print(*o)

